MERGE INTO PROSPECT.AUDITTXTPROS t USING (SELECT 7 c,'UpdatePortalAccount' a,'Update portal account' m FROM dual) s ON (t."Action Name"=s.a) WHEN NOT MATCHED THEN INSERT ("Code","Sub Code","Action Name","Message","Detail Message") VALUES (s.c,0,s.a,s.m,'Portal account administration; no passwords recorded');
MERGE INTO PROSPECT.AUDITTXTPROS t USING (SELECT 8 c,'ResetPortalLoginCount' a,'Reset invalid login count' m FROM dual) s ON (t."Action Name"=s.a) WHEN NOT MATCHED THEN INSERT ("Code","Sub Code","Action Name","Message","Detail Message") VALUES (s.c,0,s.a,s.m,'Portal account administration; no passwords recorded');
MERGE INTO PROSPECT.AUDITTXTPROS t USING (SELECT 9 c,'SetPortalPassword' a,'Set portal password' m FROM dual) s ON (t."Action Name"=s.a) WHEN NOT MATCHED THEN INSERT ("Code","Sub Code","Action Name","Message","Detail Message") VALUES (s.c,0,s.a,s.m,'Portal account administration; no passwords recorded');
MERGE INTO PROSPECT.AUDITTXTPROS t USING (SELECT 10 c,'GetPortalCustomers' a,'List portal customers' m FROM dual) s ON (t."Action Name"=s.a) WHEN NOT MATCHED THEN INSERT ("Code","Sub Code","Action Name","Message") VALUES (s.c,0,s.a,s.m);
MERGE INTO PROSPECT.AUDITTXTPROS t USING (SELECT 11 c,'GetPortalContacts' a,'List customer contacts' m FROM dual) s ON (t."Action Name"=s.a) WHEN NOT MATCHED THEN INSERT ("Code","Sub Code","Action Name","Message") VALUES (s.c,0,s.a,s.m);
COMMIT;
